178: void WorkerThread::initializeWorkerThread()
179: {
180: #if defined(OS_POSIX) && !defined(STARFISH_ANDROID)
181:     pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
182:     pthread_setcanceltype(PTHREAD_CANCEL_ASYNCHRONOUS, NULL);
183: #else
184:     STARFISH_UNSUPPORTED("Unsupported platform");
185: #endif
186: }
187:
188: void WorkerThread::destroyWorkerThread()
189: {
190: #if defined(OS_POSIX) && !defined(STARFISH_ANDROID)
191:     pthread_cancel(m_workerThread.native_handle());
192: #else
193:     STARFISH_UNSUPPORTED("Unsupported platform");
194: #endif

41: void WorkerHost::run(void* data)
42: {
43:     STARFISH_ASSERT(Escargot::Globals::supportsThreading());
44:     Escargot::Globals::initializeThread();
45:
46:     RunLoop* runLoop = RunLoop::create();
47:     WorkerThread* workerThread = static_cast<WorkerThread*>(data);
48:
49:     WorkerHost host = WorkerHost(workerThread, runLoop);
50:
51:     if (!workerThread->wasTerminated()) {
52:         workerThread->onWorkerRunLoopStarted(runLoop);
53:         runLoop->run();
54:     }
55:
56:     host.dispose();
57:
58:     delete runLoop;
59:
60:     Escargot::Globals::finalizeThread();
61: }

442: void __kmp_terminate_thread(int gtid) {
443:   int status;
444:   kmp_info_t *th = __kmp_threads[gtid];
445:
446:   if (!th)
447:     return;
448:
449: #ifdef KMP_CANCEL_THREADS
450:   KA_TRACE(10, ("__kmp_terminate_thread: kill (%d)\n", gtid));
451:   status = pthread_cancel(th->th.th_info.ds.ds_thread);
452:   if (status != 0 && status != ESRCH) {
453:     __kmp_fatal(KMP_MSG(CantTerminateWorkerThread), KMP_ERR(status),
454:                 __kmp_msg_null);
455:   }
456: #endif
457:   KMP_YIELD(TRUE);
458: } //

